import{_ as r,c as l,o as t,ag as o}from"./chunks/framework.CyMCuEUM.js";const c=JSON.parse('{"title":"PolarDB 详解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/containerization-and-cloud-native/polardb.md","filePath":"guide/containerization-and-cloud-native/polardb.md"}'),i={name:"guide/containerization-and-cloud-native/polardb.md"};function n(s,a,e,h,g,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="polardb-详解" tabindex="-1">PolarDB 详解 <a class="header-anchor" href="#polardb-详解" aria-label="Permalink to &quot;PolarDB 详解&quot;">​</a></h1><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-概述">概述</a></li><li><a href="#2-核心特性与架构">核心特性与架构</a></li><li><a href="#3-mysql-兼容性">MySQL 兼容性</a></li><li><a href="#4-存储与计算分离架构">存储与计算分离架构</a></li><li><a href="#5-使用场景与优势">使用场景与优势</a></li><li><a href="#6-部署与管理">部署与管理</a></li><li><a href="#7-最佳实践">最佳实践</a></li><li><a href="#8-总结">总结</a></li></ol><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>PolarDB 是阿里云自研的云原生关系型数据库服务，采用存储与计算分离的创新架构。该数据库系统是对传统 MySQL 架构的彻底革新，既保持了与 MySQL 的完全兼容，又实现了极致弹性、高性能和高性价比。</p><h3 id="_1-1-polardb-的发展历程" tabindex="-1">1.1 PolarDB 的发展历程 <a class="header-anchor" href="#_1-1-polardb-的发展历程" aria-label="Permalink to &quot;1.1 PolarDB 的发展历程&quot;">​</a></h3><p>PolarDB 于 2017 年 10 月在云栖大会上首次发布，经过几年的发展，已成为阿里云的核心数据库产品之一。PolarDB 采用了多种前沿技术，包括存储与计算分离、高速 RDMA 网络、共享分布式存储和智能缓冲池等，实现了数据库系统在性能、可扩展性和可靠性方面的重大突破。</p><h3 id="_1-2-版本与生态" tabindex="-1">1.2 版本与生态 <a class="header-anchor" href="#_1-2-版本与生态" aria-label="Permalink to &quot;1.2 版本与生态&quot;">​</a></h3><p>目前，PolarDB 提供了三种主要版本，以满足不同用户的需求：</p><ol><li><strong>PolarDB for MySQL</strong>：与 MySQL 完全兼容，提供强大的读写分离和弹性伸缩能力</li><li><strong>PolarDB for PostgreSQL</strong>：与 PostgreSQL 兼容，提供企业级功能和性能</li><li><strong>PolarDB for Oracle</strong>：提供高度 Oracle 兼容性，帮助企业平滑迁移</li></ol><p>此外，PolarDB 还推出了专门面向特定场景的解决方案，如 PolarDB-X（分布式版本）和 PolarDB for 电商场景等。</p><h3 id="_1-3-技术创新" tabindex="-1">1.3 技术创新 <a class="header-anchor" href="#_1-3-技术创新" aria-label="Permalink to &quot;1.3 技术创新&quot;">​</a></h3><p>PolarDB 的技术创新主要体现在以下几个方面：</p><ul><li><strong>存储与计算分离</strong>：将存储和计算资源完全解耦，根据业务需求独立扩展</li><li><strong>高速网络</strong>：使用 RDMA 网络技术，提供低延迟、高带宽的数据传输能力</li><li><strong>共享存储架构</strong>：多个计算节点共享同一份数据，避免数据冗余</li><li><strong>智能缓冲池</strong>：实现跨节点的智能缓存共享和一致性保证</li><li><strong>日志即数据库</strong>：通过优化日志处理流程，显著提高写入性能</li></ul><h2 id="_2-核心特性与架构" tabindex="-1">2. 核心特性与架构 <a class="header-anchor" href="#_2-核心特性与架构" aria-label="Permalink to &quot;2. 核心特性与架构&quot;">​</a></h2><p>PolarDB 的核心特性与其独特的架构设计紧密相关。以下是 PolarDB 的主要特性：</p><h3 id="_2-1-极致弹性" tabindex="-1">2.1 极致弹性 <a class="header-anchor" href="#_2-1-极致弹性" aria-label="Permalink to &quot;2.1 极致弹性&quot;">​</a></h3><p>PolarDB 支持计算节点和存储资源的独立伸缩：</p><ul><li><strong>计算节点扩展</strong>：支持最多 16 个读写节点，可根据业务负载动态增删节点</li><li><strong>存储容量扩展</strong>：单库最大支持 100TB 的存储容量，支持在线扩容</li><li><strong>快速伸缩</strong>：存储扩展可在 3-5 分钟内完成，计算节点伸缩可在 30 秒内完成</li></ul><h3 id="_2-2-高性能" tabindex="-1">2.2 高性能 <a class="header-anchor" href="#_2-2-高性能" aria-label="Permalink to &quot;2.2 高性能&quot;">​</a></h3><p>PolarDB 在性能方面有以下优势：</p><ul><li><strong>读性能</strong>：读性能可达 100 万 QPS，是传统 MySQL 的 6 倍</li><li><strong>写性能</strong>：写性能比传统 MySQL 提升 50% 以上</li><li><strong>IOPS 能力</strong>：单库最大支持 15 万 IOPS</li></ul><h3 id="_2-3-高可用性" tabindex="-1">2.3 高可用性 <a class="header-anchor" href="#_2-3-高可用性" aria-label="Permalink to &quot;2.3 高可用性&quot;">​</a></h3><ul><li><strong>多副本机制</strong>：自动管理多个数据副本，保障数据安全性</li><li><strong>故障快速切换</strong>：计算节点故障可在 10 秒内完成切换</li><li><strong>跨可用区部署</strong>：支持跨多个可用区的多副本部署，实现机房级容灾</li></ul><h3 id="_2-4-架构组成" tabindex="-1">2.4 架构组成 <a class="header-anchor" href="#_2-4-架构组成" aria-label="Permalink to &quot;2.4 架构组成&quot;">​</a></h3><p>PolarDB 的架构主要由以下几个核心组件构成：</p><ol><li><strong>计算节点</strong>：负责处理 SQL 请求和事务，兼容 MySQL 协议</li><li><strong>存储节点</strong>：提供分布式存储服务，存储数据库的实际数据</li><li><strong>共享存储</strong>：使用分布式文件系统，为多个计算节点提供共享访问</li><li><strong>日志系统</strong>：处理 WAL 日志，实现持久化和一致性</li><li><strong>全局事务管理器</strong>：管理分布式事务，保证 ACID 特性</li></ol><h2 id="_3-mysql-兼容性" tabindex="-1">3. MySQL 兼容性 <a class="header-anchor" href="#_3-mysql-兼容性" aria-label="Permalink to &quot;3. MySQL 兼容性&quot;">​</a></h2><p>PolarDB for MySQL 与 MySQL 协议完全兼容，这是其核心优势之一。这种兼容性为用户提供了以下便利：</p><h3 id="_3-1-协议与-api-兼容性" tabindex="-1">3.1 协议与 API 兼容性 <a class="header-anchor" href="#_3-1-协议与-api-兼容性" aria-label="Permalink to &quot;3.1 协议与 API 兼容性&quot;">​</a></h3><ul><li><strong>标准 MySQL 协议</strong>：支持标准 MySQL 协议，可以使用任何 MySQL 客户端连接</li><li><strong>SQL 语法兼容</strong>：99% 的 MySQL SQL 语法在 PolarDB 中得到支持</li><li><strong>存储引擎兼容性</strong>：支持 InnoDB 存储引擎，并进行了大量优化</li><li><strong>函数与特性支持</strong>：支持 MySQL 的所有主要函数和特性</li></ul><h3 id="_3-2-迁移便利" tabindex="-1">3.2 迁移便利 <a class="header-anchor" href="#_3-2-迁移便利" aria-label="Permalink to &quot;3.2 迁移便利&quot;">​</a></h3><ul><li><strong>最小化迁移成本</strong>：无需修改应用程序代码，可直接使用 MySQL 连接</li><li><strong>数据迁移工具</strong>：提供多种数据迁移工具，包括 DTS、mysqldump 等</li><li><strong>在线迁移</strong>：支持在线迁移，最大限度减少业务中断时间</li></ul><h3 id="_3-3-特性对比" tabindex="-1">3.3 特性对比 <a class="header-anchor" href="#_3-3-特性对比" aria-label="Permalink to &quot;3.3 特性对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>MySQL</th><th>PolarDB for MySQL</th></tr></thead><tbody><tr><td>最大连接数</td><td>4,000</td><td>100,000+</td></tr><tr><td>最大数据量</td><td>取决于磁盘空间</td><td>100TB</td></tr><tr><td>读性能</td><td>10-15 万 QPS</td><td>100 万 QPS</td></tr><tr><td>写性能</td><td>2-5 万 QPS</td><td>10-15 万 QPS</td></tr><tr><td>扩展性</td><td>垂直扩展为主</td><td>存储与计算分离</td></tr><tr><td>高可用</td><td>主从复制</td><td>共享存储、多副本</td></tr></tbody></table><h2 id="_4-存储与计算分离架构" tabindex="-1">4. 存储与计算分离架构 <a class="header-anchor" href="#_4-存储与计算分离架构" aria-label="Permalink to &quot;4. 存储与计算分离架构&quot;">​</a></h2><p>存储与计算分离是 PolarDB 的核心创新，它为数据库带来了前所未有的弹性、性能和成本优势。</p><h3 id="_4-1-架构优势" tabindex="-1">4.1 架构优势 <a class="header-anchor" href="#_4-1-架构优势" aria-label="Permalink to &quot;4.1 架构优势&quot;">​</a></h3><p>存储与计算分离架构的主要优势包括：</p><ol><li><strong>独立伸缩</strong>：存储和计算资源可根据实际需求独立扩展</li><li><strong>资源优化</strong>：计算节点可根据负载弹性伸缩，存储资源按需分配</li><li><strong>共享数据</strong>：多个计算节点共享同一份数据，避免数据冗余</li><li><strong>快速切换</strong>：计算节点故障切换时无需复制大量数据</li><li><strong>成本效益</strong>：资源利用率更高，总体拥有成本更低</li></ol><h3 id="_4-2-工作原理" tabindex="-1">4.2 工作原理 <a class="header-anchor" href="#_4-2-工作原理" aria-label="Permalink to &quot;4.2 工作原理&quot;">​</a></h3><p>PolarDB 的存储与计算分离架构工作原理如下：</p><ol><li><strong>数据存储</strong>：所有数据存储在共享的分布式存储系统中，多个计算节点可同时访问</li><li><strong>日志处理</strong>：事务日志存储在高性能的存储节点中，并进行实时持久化</li><li><strong>缓存共享</strong>：通过全局缓存层，实现多个计算节点间的缓存共享</li><li><strong>事务协调</strong>：通过全局事务管理器协调多个计算节点间的事务</li></ol><h3 id="_4-3-关键技术" tabindex="-1">4.3 关键技术 <a class="header-anchor" href="#_4-3-关键技术" aria-label="Permalink to &quot;4.3 关键技术&quot;">​</a></h3><p>实现存储与计算分离的关键技术包括：</p><ul><li><strong>RDMA 网络</strong>：使用 RDMA 技术实现计算节点与存储节点间的高性能通信</li><li><strong>共享存储文件系统</strong>：设计专门的分布式文件系统，支持多主机并发访问</li><li><strong>智能缓存管理</strong>：实现跨节点的智能缓存共享和一致性管理</li><li><strong>分布式事务</strong>：实现跨节点的分布式事务处理，保证数据一致性</li></ul><h2 id="_5-使用场景与优势" tabindex="-1">5. 使用场景与优势 <a class="header-anchor" href="#_5-使用场景与优势" aria-label="Permalink to &quot;5. 使用场景与优势&quot;">​</a></h2><p>PolarDB 适用于多种业务场景，特别适合对性能、弹性和成本有较高要求的应用。</p><h3 id="_5-1-典型应用场景" tabindex="-1">5.1 典型应用场景 <a class="header-anchor" href="#_5-1-典型应用场景" aria-label="Permalink to &quot;5.1 典型应用场景&quot;">​</a></h3><ul><li><strong>电商系统</strong>：处理高并发读写请求，支持大规模促销活动</li><li><strong>互联网应用</strong>：支持快速增长的业务数据量和用户量</li><li><strong>金融系统</strong>：满足高一致性和高可用性要求</li><li><strong>物联网</strong>：处理海量时序数据和实时分析需求</li><li><strong>SaaS 应用</strong>：支持多租户架构和弹性资源分配</li></ul><h3 id="_5-2-主要优势" tabindex="-1">5.2 主要优势 <a class="header-anchor" href="#_5-2-主要优势" aria-label="Permalink to &quot;5.2 主要优势&quot;">​</a></h3><p>PolarDB 的主要优势包括：</p><ol><li><strong>极致弹性</strong>：存储与计算独立扩展，无停机扩容</li><li><strong>高性能</strong>：读性能达到 100 万 QPS，写性能显著提升</li><li><strong>高可用</strong>：多副本机制，故障快速切换</li><li><strong>成本效益</strong>：按使用量计费，资源利用率高</li><li><strong>易用性</strong>：与 MySQL 完全兼容，迁移成本低</li><li><strong>智能运维</strong>：内置智能调优和故障诊断功能</li></ol><h3 id="_5-3-性能对比" tabindex="-1">5.3 性能对比 <a class="header-anchor" href="#_5-3-性能对比" aria-label="Permalink to &quot;5.3 性能对比&quot;">​</a></h3><p>在典型业务场景下，PolarDB 相比传统 MySQL 的性能提升：</p><ul><li><strong>读密集型应用</strong>：性能提升 6-10 倍</li><li><strong>写密集型应用</strong>：性能提升 2-3 倍</li><li><strong>混合读写场景</strong>：综合性能提升 3-5 倍</li></ul><h2 id="_6-部署与管理" tabindex="-1">6. 部署与管理 <a class="header-anchor" href="#_6-部署与管理" aria-label="Permalink to &quot;6. 部署与管理&quot;">​</a></h2><p>PolarDB 提供了多种部署和管理方式，满足不同用户的需求。</p><h3 id="_6-1-部署方式" tabindex="-1">6.1 部署方式 <a class="header-anchor" href="#_6-1-部署方式" aria-label="Permalink to &quot;6.1 部署方式&quot;">​</a></h3><ul><li><strong>云托管版本</strong>：阿里云直接提供，无需自行部署</li><li><strong>混合云版本</strong>：支持本地数据中心与云环境的混合部署</li><li><strong>私有云版本</strong>：在企业自有环境中部署完整解决方案</li></ul><h3 id="_6-2-管理控制台" tabindex="-1">6.2 管理控制台 <a class="header-anchor" href="#_6-2-管理控制台" aria-label="Permalink to &quot;6.2 管理控制台&quot;">​</a></h3><p>PolarDB 提供了直观易用的管理控制台，支持：</p><ul><li><strong>集群管理</strong>：创建、删除和修改集群</li><li><strong>实例管理</strong>：管理计算节点和存储实例</li><li><strong>监控与告警</strong>：实时监控数据库性能和状态，设置告警规则</li><li><strong>备份与恢复</strong>：配置自动备份，执行数据恢复</li><li><strong>性能优化</strong>：分析慢查询，提供优化建议</li></ul><h3 id="_6-3-监控与诊断" tabindex="-1">6.3 监控与诊断 <a class="header-anchor" href="#_6-3-监控与诊断" aria-label="Permalink to &quot;6.3 监控与诊断&quot;">​</a></h3><ul><li><strong>性能指标</strong>：提供详细的性能监控指标和可视化图表</li><li><strong>诊断工具</strong>：内置多种诊断工具，帮助定位和解决问题</li><li><strong>SQL 分析</strong>：提供 SQL 执行计划和性能分析工具</li><li><strong>系统诊断</strong>：提供系统资源使用情况和潜在问题分析</li></ul><h2 id="_7-最佳实践" tabindex="-1">7. 最佳实践 <a class="header-anchor" href="#_7-最佳实践" aria-label="Permalink to &quot;7. 最佳实践&quot;">​</a></h2><p>使用 PolarDB 时，以下是一些推荐的最佳实践：</p><h3 id="_7-1-设计优化" tabindex="-1">7.1 设计优化 <a class="header-anchor" href="#_7-1-设计优化" aria-label="Permalink to &quot;7.1 设计优化&quot;">​</a></h3><ul><li><strong>表设计</strong>：遵循 MySQL 的表设计最佳实践，注意分区表的使用</li><li><strong>索引优化</strong>：合理创建索引，避免过度索引</li><li><strong>数据类型</strong>：选择合适的数据类型，注意 varchar 与 char 的区别</li><li><strong>分区表</strong>：利用分区表提高查询性能和管理效率</li></ul><h3 id="_7-2-查询优化" tabindex="-1">7.2 查询优化 <a class="header-anchor" href="#_7-2-查询优化" aria-label="Permalink to &quot;7.2 查询优化&quot;">​</a></h3><ul><li><strong>SQL 编写</strong>：编写高效的 SQL 语句，避免全表扫描</li><li><strong>连接池</strong>：使用连接池管理数据库连接，提高效率</li><li><strong>读写分离</strong>：利用 PolarDB 的读写分离能力，平衡读写负载</li><li><strong>执行计划</strong>：定期分析慢查询和执行计划，进行针对性优化</li></ul><h3 id="_7-3-架构建议" tabindex="-1">7.3 架构建议 <a class="header-anchor" href="#_7-3-架构建议" aria-label="Permalink to &quot;7.3 架构建议&quot;">​</a></h3><ul><li><strong>服务化架构</strong>：采用服务化架构，简化数据库访问</li><li><strong>缓存层</strong>：在应用层增加缓存层，减少数据库压力</li><li><strong>容量规划</strong>：合理规划数据库容量和扩展策略</li><li><strong>监控告警</strong>：建立完善的监控和告警机制</li></ul><h2 id="_8-总结" tabindex="-1">8. 总结 <a class="header-anchor" href="#_8-总结" aria-label="Permalink to &quot;8. 总结&quot;">​</a></h2><p>PolarDB 作为阿里云自研的云原生数据库，通过存储与计算分离的创新架构，在保持与 MySQL 高度兼容的同时，实现了性能、弹性和成本的多重突破。其极致弹性、高性能、高可用性和成本效益，使其成为现代企业数据库的理想选择，特别是对于需要处理大规模数据和复杂查询的企业级应用。</p><p>随着云原生技术的不断发展和企业数字化转型的深入，PolarDB 将在帮助企业构建高效、可靠的数据基础设施方面发挥重要作用。对于正在考虑数据库升级或迁移的企业来说，PolarDB 提供了极具吸引力的解决方案，值得深入研究和应用。</p>',76)])])}const P=r(i,[["render",n]]);export{c as __pageData,P as default};
